def minPath(grid, k):
    n = len(grid)
    # locate the cell containing 1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                x, y = i, j

    # smallest neighbor of the cell containing 1
    best = n * n + 1
    for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        a, b = x + dx, y + dy
        if 0 <= a < n and 0 <= b < n:
            best = min(best, grid[a][b])

    # alternate between 1 and the smallest neighbor
    return [1 if i % 2 == 0 else best for i in range(k)]
