def amicable_numbers_sum(n):
    """Return the sum of all amicable numbers in the range 1..n."""

    def sum_proper_divisors(num):
        if num < 2:
            return 0
        total = 1  # 1 is a proper divisor of every num >= 2
        i = 2
        while i * i <= num:
            if num % i == 0:
                total += i
                other = num // i
                if other != i:
                    total += other
            i += 1
        return total

    amicable = set()
    for a in range(2, n + 1):
        b = sum_proper_divisors(a)
        if b != a and b <= n and sum_proper_divisors(b) == a:
            amicable.add(a)
            amicable.add(b)

    return sum(amicable)


