def find_solution(a, b, n):
    # Nonnegative solutions: try x = 0, 1, 2, ... (smallest x first)
    if a > 0 and b > 0 and n >= 0:
        i = 0
        while i * a <= n:
            if (n - i * a) % b == 0:
                return (i, (n - i * a) // b)
            i += 1
        return None

    # General case (zero or negative inputs): extended Euclid
    def egcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, s, t = egcd(y, x % y)
        return (g, t, s - (x // y) * t)

