def find_solution(a, b, n):
    def extended_gcd(p, q):
        # returns (g, s, t) with s*p + t*q = g = gcd(p, q)
        if q == 0:
            return (p, 1, 0)
        g, s, t = extended_gcd(q, p % q)
        return (g, t, s - (p // q) * t)

    g, _, _ = extended_gcd(a, b)
    if n % g != 0:
        return None

    a1, b1, n1 = a // g, b // g, n // g

    if b1 == 1:
        x = 0
    else:
        # inverse of a1 modulo b1
        _, s, _ = extended_gcd(a1 % b1, b1)
        inv = s % b1
        x = (n1 * inv) % b1  # smallest non-negative x

    y = (n - a * x) // b
    return (x, y)


