            elif j == i + 1:
                dp[i][j] = (s[i] == s[j])
            else:
                dp[i][j] = (s[i] == s[j] and dp[i + 1][j - 1])
    # dp[i][j] will be true if the subsequence from i to j is the longest palindrome
    max_len = 0
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if dp[i][j] and j - i + 1 > max_len:
